  "browserLocal.badge": "Browser local mode",
  "browserLocal.badgeAria": "Browser local mode: view available features and limits",
  "browserLocal.title": "Browser local mode",
  "browserLocal.intro": "This page is running in a browser without the MinCode desktop app. Only the features below really work here; everything else is marked desktop-only.",
  "browserLocal.featuresTitle": "Available in the browser",
  "browserLocal.featuresEmpty": "Apart from the interface, no features are available in the browser yet.",
  "browserLocal.limitations": "Browsers enforce cross-origin, permission, and storage limits: requests fail when the target does not allow cross-origin access, and data stays in this browser only. Use the desktop app for full functionality.",
  "browserLocal.feature.http.title": "HTTP requests",
  "browserLocal.feature.http.limit": "Sent by the browser: the target must allow cross-origin access (CORS); restricted headers such as Cookie and Host are not sent, and only response headers the target exposes are visible; requests with custom headers or a body do not follow redirects; picked files are lost on reload. WebSocket, SSE, Socket.IO, Mock, collection runs and code generation are desktop-only.",
  "browserLocal.feature.ai.title": "AI chat",
  "browserLocal.feature.ai.limit": "Plain chat: requests go straight from the browser to the AI provider, which must allow cross-origin access (CORS); no tools, MCP or approvals; the API key is kept in this tab only and cleared when it closes; conversations are saved in this browser. External agents (ACP) and subtasks are desktop-only.",
  "browserLocal.feature.project.title": "Local projects",
  "browserLocal.feature.project.limit": "Opens a folder on this computer through the browser's folder access (Chrome / Edge only): browse, edit text, preview images, create, rename, delete and search. After reloading the page, click \"Re-authorize\" to regain access. Regex search and replace, Git, terminal, language servers, project index, external files, pasting files, revealing in Finder and deployment are desktop-only.",
  "ai.browser.corsError": "The AI provider does not allow cross-origin access from the browser, or the network is unreachable. Use the desktop app, or a service URL that allows cross-origin requests (CORS).",
  "ai.browser.streamInterrupted": "The AI response stream was interrupted: the browser lost its connection to the provider.",
  "ai.browser.timeout": "The AI request timed out",
  "settings.ai.browserKeyNote": "Browser local mode: the key is kept in this tab only and cleared when it closes; requests go straight from the browser to the provider, which must allow cross-origin access.",
  "http.browser.corsError": "The target does not allow cross-origin access from the browser, or the network is unreachable. Use the desktop app to send this request.",
  "http.browser.timeout": "Request timed out",
  "http.browser.invalidUrl": "The browser can only request http:// or https:// URLs",
  "http.browser.fileUnavailable": "The file to upload is missing: files picked in the browser are lost when the page reloads. Choose the file again.",
  "http.browser.uploadTooLarge": "Upload exceeds the 25 MB limit",
  "http.browser.headersDropped": "The browser does not let web pages set these request headers, so they were not sent: {headers}",
  "http.browser.bodyDropped": "The browser does not allow a body on {method} requests, so the body was not sent.",
  "http.browser.redirectBlocked": "The target responded with a redirect. This request carries custom headers or a body, which the browser cannot follow safely (they could be forwarded to another site), so it was stopped. Use the desktop app to send this request.",
  "http.browser.redirectDowngraded": "The request was redirected to an unencrypted HTTP address: {url}",
